const TRAILING = new Set(['nqt', 'limited', 'ltd', 'pvt', 'private', 'inc', 'corp', 'corporation', 'technologies', 'technology', 'india', 'hiring', 'exam', 'test', 'placement']);

/** { path, color } for a company name, or null when we have no free mark for it. */
export function getBrandLogo(name) {
  if (!SHOW_BRAND_LOGOS) return null;
  const words = String(name || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  while (words.length) {
    const key = words.join('');
    const hit = ICONS[ALIAS[key] || key];
    if (hit) return { path: hit[0], color: `#${hit[1]}` };
    if (words.length > 1 && TRAILING.has(words[words.length - 1])) words.pop();
    else break;
  }
  return null;
}
